/* Run the global board only after durable storage is hydrated. */
(async function(){
 try{await PagesStore.initialize();const source=document.getElementById('pagesBoardSource');const script=document.createElement('script');script.textContent=source.textContent;document.body.append(script);window.ReleaseBoardLoaded=true;window.dispatchEvent(new Event('boardready'));}
 catch(error){const box=document.createElement('section');box.className='card';const message=document.createElement('p');message.textContent='工作台未打开：'+error.message;box.append(message);for(const [label,action] of [['下载存储恢复包',async()=>PagesStore.download('storage-recovery.json',JSON.stringify(await PagesStore.storageRecovery(),null,2))],['采用已校验数据库继续',async()=>{PagesStore.download('storage-recovery.json',JSON.stringify(await PagesStore.storageRecovery(),null,2));if(confirm('已发起恢复包下载。确认采用数据库中的已校验记录继续？')){await PagesStore.adoptIndexedDBStorage();location.reload();}}],['采用旧版记录重新迁移',async()=>{PagesStore.download('storage-recovery.json',JSON.stringify(await PagesStore.storageRecovery(),null,2));if(confirm('已发起恢复包下载。确认采用当前旧版记录重新迁移？现有数据库版本仍保留在恢复包中。')){await PagesStore.adoptLegacyStorage();location.reload();}}]]){const button=document.createElement('button');button.className='btn';button.textContent=label;button.onclick=()=>action().catch(e=>message.textContent=e.message);box.append(button);}document.body.prepend(box);}
})();
